Here is a C++ class named `KParseItem` that reads a text file, parses each item, and stores the item name and data into a `StItem` struct:
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <sstream>
#include <vector>

class KParseItem
{
public:
    KParseItem() {}
    ~KParseItem() {}

    void Parse(const std::string& filename)
    {
        std::ifstream file(filename);
        if (!file.is_open())
        {
            std::cerr << "Error: cannot open file " << filename << std::endl;
            return;
        }

        std::string line;
        std::vector<StItem> items;
        while (std::getline(file, line))
        {
            if (line[0] == '[')
            {
                std::string name = line.substr(line.find('_') + 1);
                items.push_back({name, line.substr(line.find('_') + 1)});
                line.erase(line.find('_') + 1);
            }
            else
            {
                items.back().Data += line + "\n";
            }
        }

        items.back().Data += line;
        file.close();
    }

private:
    std::vector<StItem> items;
};
```
To use this class, you can create an instance of `KParseItem`, and then call the `Parse` method, passing in the filename of the text file to parse:
```cpp
KParseItem kparse;
kparse.Parse("file.txt");
```
This will parse the text file and store each item's name and data into the `StItem` struct in the `items` vector.

