def sort_asc(arr):
    n = len(arr)
    # Traverse through all pairs of elements and swap if they are in the wrong order
    for i in range(0, n-1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr
