    const visited = new Set<string>();
    const dist = new Map<string, number>();
    const prev = new Map<string, number>();

    dist.set(start, 0);
    visited.add(start);

    for (let i = 1; i < list.length; i++) {
        const cur = list[i];

        if (!visited.has(cur[0])) {
            let minDist = Infinity;
            const node = list[i][1];

            for (let j = 0; j < prev.size; j++) {
                const prevNode = prev.get(prev[j]);

                if (node == prevNode || !visited.has(prevNode)) {
                    continue;
                }

                const distToNode = cur[1] + dist.get(prevNode);
                if (distToNode < minDist) {
                    minDist = distToNode;
                }
            }

            prev.set(node, cur[0]);
            dist.set(cur[0], minDist);
            visited.add(cur[0]);
        }
    }

    return list;
}
