Voici un exemple de code C# pour créer un serveur HTTP simple avec HttpListener et afficher un message "Hello" sur la page "index.html" sur le port 8080 :
```csharp
using System;
using System.Net;
using System.Threading.Tasks;
using System.Web;

class Program
{
    static void Main(string[] args)
    {
        // Crée un objet HttpListener pour écouter les demandes HTTP
        var listener = new HttpListener();

        // Définir les paramètres de configuration pour l'écoute des demandes
        listener.Prefixes.Add("http://*:8080/");
        listener.Start();

        // Attendre que les demandes arrivent
        while (true)
        {
            // Vérifier si une demande est arrivée
            var context = listener.GetContext();
            if (context != null)
            {
                // Obtenir le stream de la demande
                var request = context.Request;

                // Vérifier si la demande est pour la page "index.html"
                if (request.Url.AbsolutePath == "/index.html")
                {
                    // Afficher le message "Hello" sur la page "index.html"
                    var response = context.Response;
                    response.ContentType = "text/html";
                    response.Write("Hello");
                    response.End();
                }
                else
                {
                    // Renvoyer une erreur 404 pour les autres demandes
                    var response = context.Response;
                    response.StatusCode = 404;
                    response.ContentType = "text/plain";
                    response.Write("404 Not Found");
                    response.End();
                }
            }
        }

        // Arrêter l'écoute des demandes
        listener.Stop();
    }
}
```
Ce code utilise l'objet `HttpListener` pour écouter les demandes HTTP sur le port 8080. Lorsqu'une demande est reçue pour la page "index.html", le message "Hello" est affiché sur cette page. Pour toutes les autres demandes, une erreur 404 est renvoyée.

