void MoveCharacter(float horizontal, float vertical, float speed)
{
    // Movimentação no eixo X
    transform.position += transform.right * horizontal * speed * Time.deltaTime;

    // Movimentação no eixo Z
    transform.position += transform.forward * vertical * speed * Time.deltaTime;

    // Limita a rotação no eixo Y entre -90 e 90 graus
    transform.eulerAngles = new Vector3(0, Mathf.Clamp(transform.eulerAngles.y, -90, 90), 0);

    // Rotaciona o personagem na direção da movimentação
