double get_sqrt(double val) {
    double x;
    double y;
    double error;
    double delta = 0.000001;
    int i=0;
    while(fabs(y - x) > delta) {
        x = x + y / x;
        y = val - x * x / (2.0 * y);
        error = fabs(x - y);
        if(error < 0.000001) {
            break;
        }
        i++;
    }
    return x;
}
