Here's a C program that converts a base-10 value from 1 to 3999 into a Roman numeral using bitmasking:


```c
#include <stdio.h>

int main() {
    int n, result[3999];

    for (n = 1; n <= 3999; n++) {
        int i = 0, j = 0, k = 0;
        while (n) {
            i = n % 10;
            n = n / 10;
            result[k++] = (i * 5) + (i >> 3);
        }
    }

    for (n = 1; n <= 3999; n++) {
        int i = 0, j = 0, k = 0;
        while (n) {
            i = result[n % 3999];
            n = n / 3999;
            result[k++] = i;
        }
    }

    printf("The Roman numeral for %d is: ", 1);
    for (n = 1; n <= 3999; n++) {
        int i = result[n % 3999];
        printf("%c", i);
    }
    return 0;
}

```

