Sure! Here's an implementation of the quick sort algorithm in C:

```c
void quick_sort(int *arr, int left, int right) {
    int i, last;
    int pivot = arr[left];

    /* Move the pivot to the right place */
    for (i = left; i < right; i++) {
        if (arr[i] < pivot) {
            last = i;
            i++;
        }
    }

    /* Swap the pivot with the last element */
    if (last != right) {
        arr[i] = arr[last];
        arr[last] = pivot;
    }

    /* Recursively sort the left and right partitions */
    quick_sort(arr, left, last-1);
    quick_sort(arr, last+1, right);
}

void print_array(int *arr, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int arr[] = {12, 11, 13, 5, 6, 7, 4, 9, 10, 8, 14, 15, 3, 2, 0};
    int size = sizeof(arr)/sizeof(arr[0]);
    print_array(arr, size);

    quick_sort(arr, 0, size-1);

    print_array(arr, size);

    return 0;
}
```

In this implementation, the quick sort algorithm is broken down into two recursive calls: one to sort the left partition and one to sort the right partition. The algorithm also uses the last element in the left partition as the pivot. The performance of this implementation can be improved by choosing a better pivot strategy, such as the median-of-three strategy or the randomized pivot strategy.

Here is a Python program that uses a stack class to check for balanced parentheses in an expression:
```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.items:
            raise ValueError('Stack is empty')
        return self.items.pop()

    def peek(self):
        if not self.items:
            raise ValueError('Stack is empty')
        return self.items[-1]

    def is_balanced(self):
        if not self.items:
            return True
        if self.peek() != '(':
            return False
        if not self.pop():
            return False
        if self.is_balanced():
            return True
        if self.peek() != ')':
            return False
        if not self.pop():
            return False
        return self.is_balanced()

def main():
    stack = Stack()
    stack.push('(')
    stack.push('a')
    stack.push('b')
    stack.push('c')
    stack.push('d')
    stack.push(')')
    print(stack.is_balanced()) # should print True
    stack.pop() # should not raise an error
    print(stack.is_balanced()) # should print False
if __name__ == '__main__':
    main()
```
