public class LoggingTransformer implements ClassFileTransformer {
    @Override
    public byte[] transform(ClassLoader loader, NAME_1 className, Class<?> classBeingRedefined, 
            ProtectionDomain protectionDomain, byte[] classfileBuffer) {
        if (className.startsWith("com.example")) {
            System.out.println("Transforming class: " + className);
            return addLogging(classfileBuffer);
        }
        return null; // no transformation
    }

    private byte[] addLogging(byte[] classfileBuffer) {
        ClassReader cr = new ClassReader(classfileBuffer);
        ClassWriter cw = new ClassWriter(cr, ClassWriter.COMPUTE_MAXS);
        LoggingClassVisitor cv = new LoggingClassVisitor(cw);
        cr.accept(cv, 0);
        return cw.toByteArray();
    }
}
```

Instrumentation to time method execution:
```java
public class TimingTransformer implements ClassFileTransformer {
    @Override
    public byte[] transform(ClassLoader loader, NAME_1 className, Class<?> classBeingRedefined,
            ProtectionDomain protectionDomain, byte[] classfileBuffer) {
        if (className.startsWith("com.example")) {
            System.out.println("Transforming class: " + className);
            return addTiming(classfileBuffer);
        }
        return null; 
    }

    private byte[] addTiming(byte[] classfileBuffer) {
        ClassReader cr = new ClassReader(classfileBuffer);
        ClassWriter cw = new ClassWriter(cr, ClassWriter.COMPUTE_MAXS);
        TimingClassVisitor cv = new TimingClassVisitor(cw);
        cr.accept(cv, 0);
        return cw.toByteArray();
    }
}
```

