function millisecondsToHMS(inputMilliseconds) {
  // Calculate the hours, minutes, and seconds.
  const hours = Math.floor(inputMilliseconds / (60 * 60 * 1000));
  const minutes = Math.floor((inputMilliseconds % (60 * 60 * 1000)) / (60 * 1000));
  const seconds = Math.floor((inputMilliseconds % (60 * 1000)) / 1000);
  const milliseconds = inputMilliseconds % 1000;

  // Format the time.
  const formattedTime = `${hours}:${minutes}:${seconds}.${milliseconds}`;

  return formattedTime;
}

One way to make this function more efficient would be to reduce the number of mathematical operations performed by using modulo and bitwise operations. Here's an example:
