function millisecondsToHMS(inputMilliseconds) {
  // Calculate the number of seconds, minutes, hours and days.
  const sec = inputMilliseconds % 1000;
  const min = (inputMilliseconds % (1000 * 60)) % 1000;
  const hour = (inputMilliseconds % (1000 * 60 * 60)) % 1000;
  const day = Math.floor(inputMilliseconds / (1000 * 60 * 60 * 24));

  // Format the time.
  const formattedTime = `${day || ''}:${hour || ''}:${min || ''}.${sec || ''}`;

  return formattedTime;
}
